{"implementation":"def solve(case):
    import math

    def require_mapping(value, name):
        if not isinstance(value, dict):
            raise ValueError(name + " must be an object")

    def require_number(value, name, minimum=None):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(name + " must be a number")
        value = float(value)
        if not math.isfinite(value):
            raise ValueError(name + " must be finite")
        if minimum is not None and value < minimum:
            raise ValueError(name + " is below its minimum")
        return value

    require_mapping(case, "case")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("case requires threshold and calls")

    threshold = require_number(case["threshold"], "threshold", 0.0)
    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    validated = []
    seen_ids = set()
    required = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )

    for position, call in enumerate(calls):
        require_mapping(call, "calls[%d]" % position)
        for field in required:
            if field not in call:
                raise ValueError("calls[%d] requires %s" % (position, field))

        call_id = call["call_id"]
        if not isinstance(call_id, str) or not call_id:
            raise ValueError("calls[%d].call_id must be a non-empty string" % position)
        if call_id in seen_ids:
            raise ValueError("duplicate call_id: " + call_id)
        seen_ids.add(call_id)

        loss_without = require_number(
            call["loss_without_call"],
            "calls[%d].loss_without_call" % position,
            0.0,
        )
        loss_with = require_number(
            call["loss_with_call"],
            "calls[%d].loss_with_call" % position,
            0.0,
        )
        prediction_tokens = call["prediction_tokens"]
        if (
            isinstance(prediction_tokens, bool)
            or not isinstance(prediction_tokens, int)
            or prediction_tokens < 0
        ):
            raise ValueError(
                "calls[%d].prediction_tokens must be a non-negative integer" % position
            )
        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise ValueError("calls[%d].parseable must be boolean" % position)

        validated.append(
            (call_id, loss_without, loss_with, prediction_tokens, parseable)
        )

    diagnostics = []
    accepted_call_ids = []
    for call_id, loss_without, loss_with, prediction_tokens, parseable in validated:
        normalized_weight = 1.0 / max(1, prediction_tokens)
        weighted_loss_without_call = loss_without * normalized_weight
        weighted_loss_with_call = loss_with * normalized_weight
        normalized_gain = weighted_loss_without_call - weighted_loss_with_call
        accepted = parseable and normalized_gain >= threshold

        diagnostic = {
            "call_id": call_id,
            "normalized_weight": round(normalized_weight, 8),
            "weighted_loss_without_call": round(weighted_loss_without_call, 8),
            "weighted_loss_with_call": round(weighted_loss_with_call, 8),
            "normalized_gain": round(normalized_gain, 8),
            "parseable": parseable,
            "accepted": accepted,
        }
        diagnostics.append(diagnostic)
        if diagnostic["accepted"]:
            accepted_call_ids.append(diagnostic["call_id"])

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
